def daily_temps(temps):
    answer = [0] * len(temps)
    stack = []  # days still waiting, colder toward the top
    for day, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            prev = stack.pop()
            answer[prev] = day - prev
        stack.append(day)
    return answer
print(daily_temps([73, 74, 75, 71, 69, 72, 76]))
